-- =====================================================================
-- EM Speed-to-Lead: dashboard data setup
-- Run once in Supabase -> SQL Editor. Safe to re-run (clears demo data first).
-- =====================================================================

-- 1. AD SPEND TABLE (the "ad spend sheet"; same data as em_ad_spend.csv)
create table if not exists em_ad_spend (
  spend_date  date    not null,
  source      text    not null check (source in ('meta','website','referral')),
  amount      numeric not null check (amount >= 0),
  notes       text,
  primary key (spend_date, source)
);
alter table em_ad_spend enable row level security;
delete from em_ad_spend;


-- 2. DEMO HISTORY: 30 days, flagged is_demo = true, @example.com so nothing is ever emailed
delete from em_appointments where lead_id in (select id from em_leads where is_demo);
delete from em_messages where lead_id in (select id from em_leads where is_demo);
delete from em_leads where is_demo = true;


-- 3. DASHBOARD FUNCTION: every metric, by source, never blended.
--    Cohort rule: a lead counts in the period it OPTED IN; its later booking/show counts with it.
create or replace function em_dashboard(p_from date, p_to date, p_include_demo boolean default true)
returns table (
  source text, leads int, qualified int, booked int, showed int, no_shows int,
  median_minutes_to_reply numeric, spend numeric,
  cost_per_lead numeric, cost_per_booked numeric, cost_per_show numeric, no_show_rate_pct numeric
)
language sql stable
as $$
  with s as (select unnest(array['meta','website','referral']) as source),
  l as (
    select source,
      count(*)                                         as leads,
      count(*) filter (where ai_status = 'Qualified')  as qualified,
      count(*) filter (where booked_at  is not null)   as booked,
      count(*) filter (where showed_at  is not null)   as showed,
      count(*) filter (where no_show_at is not null)   as no_shows,
      percentile_cont(0.5) within group (
        order by extract(epoch from (first_reply_at - opted_in_at)) / 60.0
      ) filter (where first_reply_at is not null)      as med
    from em_leads
    where opted_in_at >= p_from and opted_in_at < (p_to + 1)
      and (p_include_demo or is_demo = false)
    group by source
  ),
  sp as (
    select source, sum(amount) as spend from em_ad_spend
    where spend_date between p_from and p_to group by source
  )
  select s.source,
    coalesce(l.leads, 0)::int, coalesce(l.qualified, 0)::int, coalesce(l.booked, 0)::int,
    coalesce(l.showed, 0)::int, coalesce(l.no_shows, 0)::int,
    round(l.med::numeric, 1),
    round(coalesce(sp.spend, 0), 2),
    round(sp.spend / nullif(l.leads, 0), 2),
    round(sp.spend / nullif(l.booked, 0), 2),
    round(sp.spend / nullif(l.showed, 0), 2),
    round(l.no_shows::numeric / nullif(l.showed + l.no_shows, 0) * 100, 1)
  from s left join l using (source) left join sp using (source)
  order by s.source;
$$;

-- Only the server (service role) may call it; never the public/browser key.
revoke execute on function em_dashboard(date, date, boolean) from public, anon, authenticated;
grant execute on function em_dashboard(date, date, boolean) to service_role;

-- 4. CHECK: you should see 3 rows (meta, referral, website)
select * from em_dashboard('2026-09-21', '2026-10-21');
